// Run from desktop/, with preview server on :4173. No reference runtime needed:
// checked-in fixtures were generated by native Skia / original Java / AOSP C++.
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync, readdirSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { chromium } from '@playwright/test';

const folder = mkdtempSync(join(tmpdir(), 'sjtu-progress-check-'));
const json = (file) => JSON.parse(readFileSync(new URL(`reference/${file}.json`, import.meta.url)));
let browser;
try {
  execFileSync('pnpm', ['exec', 'tsc', '--ignoreConfig', '--noEmit', 'false', '--outDir', folder,
    '--target', 'es2022', '--module', 'esnext', '--moduleResolution', 'bundler', '--skipLibCheck',
    ...['path', 'motion', 'easing', 'drawing'].map((name) => `src/lib/material-progress/${name}.ts`)], { stdio: 'pipe' });
  writeFileSync(join(folder, 'package.json'), '{"type":"module"}');
  for (const file of readdirSync(folder).filter((file) => file.endsWith('.js'))) {
    const path = join(folder, file);
    writeFileSync(path, readFileSync(path, 'utf8').replace(/from '(\.\/[^']+)'/g, "from '$1.js'"));
  }
  const { createWave, displayedWave } = await import(pathToFileURL(join(folder, 'path.js')));
  const { springStep, phaseFraction, DeterminateMotion } = await import(pathToFileURL(join(folder, 'motion.js')));
  const { amplitudeOn, amplitudeOff } = await import(pathToFileURL(join(folder, 'easing.js')));
  const f = Math.fround;
  let maxPathError = 0;
  for (const expected of json('paths').cases) {
    const { width, progress, phase, amplitude, curves } = expected;
    const wave = createWave(width, 40);
    assert.equal(wave.measure.length, expected.length, 'native Skia path length');
    const actual = displayedWave(wave, width, f(2 / width),
      f((Math.trunc(f(progress * width)) - 2) / width), amplitude, phase);
    assert.equal(actual.length, curves.length);
    for (let i = 0; i < actual.length; i++) for (let j = 0; j < 4; j++) for (let k = 0; k < 2; k++) {
      const error = Math.abs(actual[i][j][k] - curves[i][j][k]);
      maxPathError = Math.max(maxPathError, error);
      assert.ok(error < 0.00001, `Skia cubic mismatch: ${JSON.stringify({ width, progress, phase, amplitude, i, j, k, error })}`);
    }
  }
  for (const [value, velocity, target, dt, nextValue, nextVelocity] of json('spring')) {
    assert.deepEqual(springStep(value, velocity, target, dt), { value: f(nextValue), velocity: f(nextVelocity) });
  }
  json('easing').forEach((samples, i) => samples.forEach((value, step) => {
    assert.equal([amplitudeOn, amplitudeOff][i](f(step / 1000)), f(value), 'AOSP PathInterpolator');
  }));
  assert.equal(phaseFraction(250, 40, 40), 0.25);
  assert.equal(phaseFraction(1250, 40, 40), 0.25);
  assert.equal(phaseFraction(250, 40, -40), 0.75);
  assert.equal(phaseFraction(250, 40, 0), 0);
  assert.equal(phaseFraction(250, 40, 40, 0), 0);
  const motion = new DeterminateMotion(amplitudeOn, amplitudeOff);
  motion.setLevel(8000, true);
  motion.frame(0, 300);
  assert.equal(motion.value, 0);
  for (let now = 16; now <= 2500; now += 16) motion.frame(now, 300);
  assert.equal(motion.value, 8000);
  assert.equal(motion.amplitude, 1);
  motion.setLevel(10000, true);
  for (let now = 2512; now <= 5012; now += 16) motion.frame(now, 300);
  assert.equal(motion.value, 10000);
  assert.equal(motion.amplitude, 0);
  motion.setLevel(4000, true);
  motion.frame(5028, 300, 0);
  assert.equal(motion.value, 4000);
  assert.equal(motion.amplitude, 1);

  const semesterMotion = new DeterminateMotion(amplitudeOn, amplitudeOff, 0, 1);
  for (const level of [0, 500, 900, 1000, 9000, 9900, 10000]) {
    semesterMotion.setLevel(level, false);
    assert.equal(semesterMotion.amplitude, 1, `full-range amplitude at ${level / 100}%`);
  }
  semesterMotion.setLevel(900, true);
  semesterMotion.frame(0, 300);
  for (let now = 16; now <= 2500; now += 16) semesterMotion.frame(now, 300);
  assert.equal(semesterMotion.value, 900);
  assert.equal(semesterMotion.amplitude, 1);
  semesterMotion.setLevel(10000, true);
  for (let now = 2512; now <= 5012; now += 16) semesterMotion.frame(now, 300);
  assert.equal(semesterMotion.value, 10000);
  assert.equal(semesterMotion.amplitude, 1);

  browser = await chromium.launch();
  const page = await browser.newPage({ viewport: { width: 600, height: 200 }, deviceScaleFactor: 1 });
  await page.route('**/__progress_reference/*.js', (route) => {
    const name = new URL(route.request().url()).pathname.split('/').pop();
    return route.fulfill({ contentType: 'text/javascript', body: readFileSync(join(folder, name), 'utf8') });
  });
  await page.goto('http://localhost:4173/');
  const raster = json('rasters');
  let maxAlphaError = 0, meanAlphaError = 0, meanColorError = 0;
  for (const item of raster.cases) {
    const actual = await page.evaluate(async ({ raster, item }) => {
      const { createWave } = await import('/__progress_reference/path.js');
      const { drawProgress } = await import('/__progress_reference/drawing.js');
      const canvas = document.createElement('canvas');
      canvas.width = raster.width; canvas.height = raster.height;
      const ctx = canvas.getContext('2d');
      const spec = { width: raster.width, thickness: 4, amplitude: 3, wavelength: 40, gap: 4, stop: 4,
        speed: 40, activeColor: raster.active, trackColor: raster.track };
      drawProgress(ctx, spec, createWave(raster.width, 40), Math.fround(item.progress), item.amplitude / 3, item.phase, true);
      return [...ctx.getImageData(0, 0, canvas.width, canvas.height).data];
    }, { raster: { ...raster, cases: undefined }, item: { ...item, rgba: undefined } });
    const expected = Buffer.from(item.rgba, 'base64');
    let sum = 0, max = 0, colorSum = 0;
    for (let i = 3; i < expected.length; i += 4) {
      const error = Math.abs(expected[i] - actual[i]);
      max = Math.max(max, error); sum += error;
      for (let k = 1; k <= 3; k++) colorSum += Math.abs(expected[i - k] * expected[i] / 255 - actual[i - k] * actual[i] / 255);
    }
    maxAlphaError = Math.max(maxAlphaError, max);
    meanAlphaError = Math.max(meanAlphaError, sum / (raster.width * raster.height));
    meanColorError = Math.max(meanColorError, colorSum / (raster.width * raster.height * 3));
    assert.ok(sum / (raster.width * raster.height) < 0.25, `native Skia raster mismatch ${JSON.stringify({ progress: item.progress, phase: item.phase, max, mean: sum / (raster.width * raster.height) })}`);
    assert.ok(colorSum / (raster.width * raster.height * 3) < 0.25, 'native Skia premultiplied colour mismatch');
  }
  console.log(JSON.stringify({ paths: 224, maxPathError, springCases: 189, easingSamples: 2002,
    rasterFrames: raster.cases.length, maxAlphaError, maxMeanAlphaError: meanAlphaError, maxMeanColorError: meanColorError }));
} finally {
  await browser?.close();
  rmSync(folder, { recursive: true, force: true });
}
